/*
 * slang_stub.c - replaces Mesa 7.8's GLSL compiler ("slang") for the
 * AmigaOS 4 OSMesa build.
 *
 * The real slang compiler needs builtin-library headers (slang_*_gc.h)
 * generated by a host tool at build time, plus src/glsl/{pp,cl}. We only
 * need fixed-function OpenGL 1.x, so glCompileShader()/glLinkProgram()
 * simply fail with an info log. ARB_vertex_program / ARB_fragment_program
 * (assembly-level programs) still work: they live in shader/ and are built.
 */
#include "main/glheader.h"
#include "main/mtypes.h"
#include "main/imports.h"
#include "shader/slang/slang_compile.h"
#include "shader/slang/slang_link.h"

static const char no_glsl_msg[] =
   "GLSL is not supported in this OSMesa build (AmigaOS 4 software Mesa)\n";

GLboolean
_slang_compile(GLcontext *ctx, struct gl_shader *shader)
{
   (void) ctx;
   if (shader) {
      shader->CompileStatus = GL_FALSE;
      if (shader->InfoLog)
         free(shader->InfoLog);
      shader->InfoLog = _mesa_strdup(no_glsl_msg);
   }
   return GL_FALSE;
}

void
_slang_link(GLcontext *ctx, GLhandleARB h, struct gl_shader_program *shProg)
{
   (void) ctx;
   (void) h;
   if (shProg) {
      shProg->LinkStatus = GL_FALSE;
      if (shProg->InfoLog)
         free(shProg->InfoLog);
      shProg->InfoLog = _mesa_strdup(no_glsl_msg);
   }
}
